@import url('https://fonts.googleapis.com/css2?family=Quicksand:wght@300;400;500;600&family=Playfair+Display:ital,wght@0,400;1,400&display=swap');

:root {
  --bg: #071e2e;
  --ink: #c8eaf5;
  --mid: #7bbfd8;
  --border: rgba(100, 200, 240, 0.2);
  --accent: #40e0d0;
  --font: 'Quicksand', sans-serif;
  --pad-x: 40px;
  --pad-top: 60px;
}

/* Deep water background */
.page {
  background:
    radial-gradient(ellipse at 20% 80%, rgba(0, 80, 120, 0.5) 0%, transparent 60%),
    radial-gradient(ellipse at 80% 20%, rgba(0, 40, 80, 0.6) 0%, transparent 60%),
    radial-gradient(ellipse at 50% 50%, rgba(5, 30, 55, 0.8) 0%, transparent 80%),
    linear-gradient(180deg, #020d18 0%, #071e2e 30%, #0a2a40 70%, #051520 100%);
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
}

/* Caustic light rays from above */
.page::before {
  content: '';
  position: fixed;
  top: -100px;
  left: 0;
  width: 100%;
  height: 60%;
  background:
    repeating-linear-gradient(
      105deg,
      transparent 0%,
      transparent 8%,
      rgba(64, 200, 230, 0.03) 9%,
      transparent 10%
    ),
    repeating-linear-gradient(
      95deg,
      transparent 0%,
      transparent 12%,
      rgba(100, 220, 255, 0.04) 13%,
      transparent 14%
    );
  animation: caustics 8s ease-in-out infinite alternate;
  pointer-events: none;
  z-index: 0;
}

/* Bubble layer */
.page::after {
  content: '○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○ ○';
  position: fixed;
  bottom: -100px;
  left: 0;
  width: 100%;
  font-size: 8px;
  letter-spacing: 60px;
  color: rgba(160, 230, 255, 0.15);
  animation: bubbleRise 12s linear infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes caustics {
  0% { transform: skewX(-2deg) translateX(-10px); opacity: 0.8; }
  50% { transform: skewX(2deg) translateX(10px); opacity: 1; }
  100% { transform: skewX(-1deg) translateX(-5px); opacity: 0.7; }
}

@keyframes bubbleRise {
  0% { transform: translateY(0); opacity: 0; }
  10% { opacity: 1; }
  90% { opacity: 0.6; }
  100% { transform: translateY(-110vh); opacity: 0; }
}

.intro, .work-section {
  position: relative;
  z-index: 1;
}

/* Intro section — like drifting in a current */
.intro {
  border-bottom: 1px solid rgba(64, 224, 208, 0.15);
  padding-bottom: 60px;
  animation: drift 10s ease-in-out infinite alternate;
}

@keyframes drift {
  0% { transform: translateX(0px) translateY(0px); }
  100% { transform: translateX(4px) translateY(-4px); }
}

.intro-headline {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  font-size: clamp(2.5rem, 6vw, 5rem);
  color: #c8eaf5;
  text-shadow:
    0 0 40px rgba(64, 224, 208, 0.4),
    0 0 80px rgba(0, 140, 200, 0.2);
  line-height: 1.15;
  letter-spacing: -0.01em;
}

.bio-text {
  color: #9acfe8;
  font-weight: 300;
  line-height: 1.9;
  font-size: 1.05rem;
  text-shadow: 0 0 20px rgba(64, 224, 208, 0.1);
}

.contact-line {
  color: var(--mid);
  border-left: 2px solid rgba(64, 224, 208, 0.3);
  padding-left: 16px;
  margin-top: 20px;
}

/* Section labels — like depth markers */
.section-label {
  font-family: 'Quicksand', sans-serif;
  font-weight: 600;
  letter-spacing: 0.25em;
  text-transform: uppercase;
  font-size: 0.7rem;
  color: var(--accent);
  opacity: 0.7;
  position: relative;
  padding-left: 20px;
}

.section-label::before {
  content: '〜';
  position: absolute;
  left: 0;
  color: var(--accent);
  animation: waveTilde 3s ease-in-out infinite;
}

@keyframes waveTilde {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

/* Work items — like drifting cards */
.work-item {
  background: rgba(10, 40, 65, 0.5);
  border: 1px solid rgba(64, 224, 208, 0.12);
  border-radius: 4px;
  backdrop-filter: blur(8px);
  transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94),
              box-shadow 0.6s ease,
              border-color 0.6s ease;
  position: relative;
  overflow: hidden;
}

.work-item::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 60%;
  height: 100%;
  background: linear-gradient(
    105deg,
    transparent 40%,
    rgba(64, 224, 208, 0.06) 50%,
    transparent 60%
  );
  animation: shimmer 6s ease-in-out infinite;
  pointer-events: none;
}

@keyframes shimmer {
  0% { left: -100%; }
  100% { left: 200%; }
}

.work-item:hover {
  transform: translateY(-6px) rotate(0.3deg);
  box-shadow:
    0 20px 60px rgba(0, 0, 0, 0.5),
    0 0 30px rgba(64, 224, 208, 0.1),
    inset 0 0 20px rgba(64, 224, 208, 0.03);
  border-color: rgba(64, 224, 208, 0.35);
}

.work-image {
  opacity: 0.85;
  filter: saturate(0.7) brightness(0.85) hue-rotate(180deg);
  transition: filter 0.6s ease, opacity 0.6s ease;
}

.work-item:hover .work-image {
  opacity: 1;
  filter: saturate(1) brightness(0.95) hue-rotate(160deg);
}

.work-title {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  color: #d4eef8;
  font-size: 1.25rem;
}

.work-desc {
  color: #7bbfd8;
  font-weight: 300;
  font-size: 0.9rem;
  line-height: 1.7;
}

/* Tags — like bioluminescent labels */
.tag {
  background: rgba(0, 100, 140, 0.3);
  border: 1px solid rgba(64, 224, 208, 0.25);
  color: #80d4e8;
  border-radius: 20px;
  padding: 3px 12px;
  font-size: 0.72rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  transition: background 0.3s ease, box-shadow 0.3s ease;
}

.tag:hover {
  background: rgba(64, 224, 208, 0.15);
  box-shadow: 0 0 12px rgba(64, 224, 208, 0.3);
}

/* Footer — the deep abyss */
footer {
  border-top: 1px solid rgba(64, 224, 208, 0.1);
  color: #4a90aa;
  margin-top: 80px;
  position: relative;
}

footer::before {
  content: '～～～～～～～～～～～～～～～～～～～～～～～～～～';
  display: block;
  color: rgba(64, 224, 208, 0.15);
  font-size: 1.2rem;
  letter-spacing: 2px;
  overflow: hidden;
  text-align: center;
  margin-bottom: 8px;
}

.footer-nav a {
  color: #4a90aa;
  transition: color 0.3s ease, text-shadow 0.3s ease;
}

.footer-nav a:hover {
  color: var(--accent);
  text-shadow: 0 0 15px rgba(64, 224, 208, 0.6);
}

/* Case study — submerged document */
.cs-title {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  color: #c8eaf5;
  text-shadow: 0 0 40px rgba(64, 224, 208, 0.3);
}

.cs-section-label {
  color: var(--accent);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-size: 0.72rem;
  opacity: 0.75;
}

.callout {
  background: rgba(0, 60, 100, 0.4);
  border-left: 3px solid rgba(64, 224, 208, 0.5);
  border-radius: 2px;
  backdrop-filter: blur(4px);
  box-shadow: inset 0 0 30px rgba(0, 100, 160, 0.1);
  color: #a8d8ee;
}

.meta-label {
  color: var(--accent);
  opacity: 0.7;
  font-size: 0.72rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.meta-value {
  color: var(--ink);
}

.back-link {
  color: var(--mid);
  transition: color 0.3s ease, letter-spacing 0.3s ease;
}

.back-link:hover {
  color: var(--accent);
  letter-spacing: 0.05em;
}

/* Popup — like a message in a bottle */
.popup-overlay {
  background: rgba(2, 15, 30, 0.88);
  backdrop-filter: blur(10px);
}

.popup-card {
  background: linear-gradient(135deg, rgba(7, 30, 50, 0.97), rgba(10, 40, 70, 0.97));
  border: 1px solid rgba(64, 224, 208, 0.2);
  box-shadow:
    0 30px 80px rgba(0, 0, 0, 0.7),
    0 0 60px rgba(64, 224, 208, 0.05);
  border-radius: 6px;
}

.popup-title {
  font-family: 'Playfair Display', serif;
  font-style: italic;
  color: #c8eaf5;
  text-shadow: 0 0 20px rgba(64, 224, 208, 0.3);
}

.popup-sub {
  color: var(--mid);
  font-weight: 300;
}

.popup-form input,
.popup-form textarea {
  background: rgba(0, 30, 55, 0.6);
  border: 1px solid rgba(64, 224, 208, 0.2);
  color: var(--ink);
  border-radius: 3px;
  transition: border-color 0.3s ease, box-shadow 0.3s ease;
}

.popup-form input:focus,
.popup-form textarea:focus {
  outline: none;
  border-color: rgba(64, 224, 208, 0.5);
  box-shadow: 0 0 20px rgba(64, 224, 208, 0.1);
}

.btn-submit {
  background: linear-gradient(135deg, rgba(0, 120, 160, 0.8), rgba(64, 200, 208, 0.6));
  border: 1px solid rgba(64, 224, 208, 0.4);
  color: #e0f6ff;
  border-radius: 3px;
  transition: all 0.4s ease;
  font-family: 'Quicksand', sans-serif;
  font-weight: 600;
  letter-spacing: 0.1em;
}

.btn-submit:hover {
  background: linear-gradient(135deg, rgba(0, 150, 190, 0.9), rgba(64, 224, 208, 0.7));
  box-shadow: 0 0 30px rgba(64, 224, 208, 0.25);
}

.btn-close {
  color: var(--mid);
  background: transparent;
  border: 1px solid rgba(64, 224, 208, 0.15);
  border-radius: 3px;
  transition: border-color 0.3s ease, color 0.3s ease;
}

.btn-close:hover {
  border-color: rgba(64, 224, 208, 0.35);
  color: var(--ink);
}

/* Contact trigger bioluminescence */
.contact-trigger {
  color: var(--accent);
  position: relative;
}

.contact-trigger::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 100%;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--accent), transparent);
  animation: glowLine 2s ease-in-out infinite;
}

@keyframes glowLine {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

