(function() {
  const canvas = document.createElement('canvas');
  canvas.style.cssText = `
    position: fixed;
    top: 0; left: 0;
    width: 100%; height: 100%;
    pointer-events: none;
    z-index: 0;
    opacity: 0.6;
  `;
  document.body.prepend(canvas);

  const ctx = canvas.getContext('2d');
  let W, H, bubbles = [], animId;

  function resize() {
    W = canvas.width = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }
  resize();
  window.addEventListener('resize', resize);

  class Bubble {
    constructor() { this.reset(); }
    reset() {
      this.x = Math.random() * W;
      this.y = H + Math.random() * 100;
      this.r = Math.random() * 4 + 1;
      this.speed = Math.random() * 0.6 + 0.2;
      this.drift = (Math.random() - 0.5) * 0.4;
      this.opacity = Math.random() * 0.3 + 0.05;
      this.wobble = Math.random() * Math.PI * 2;
      this.wobbleSpeed = Math.random() * 0.02 + 0.01;
    }
    update() {
      this.y -= this.speed;
      this.wobble += this.wobbleSpeed;
      this.x += Math.sin(this.wobble) * 0.5 + this.drift;
      if (this.y < -20) this.reset();
    }
    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(100, 210, 240, ${this.opacity})`;
      ctx.lineWidth = 0.8;
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(this.x - this.r * 0.3, this.y - this.r * 0.3, this.r * 0.25, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(200, 240, 255, ${this.opacity * 1.5})`;
      ctx.fill();
    }
  }

  for (let i = 0; i < 60; i++) {
    const b = new Bubble();
    b.y = Math.random() * H;
    bubbles.push(b);
  }

  let mouseX = -999, mouseY = -999;
  function onMouseMove(e) {
    mouseX = e.clientX;
    mouseY = e.clientY;
  }
  window.addEventListener('mousemove', onMouseMove);

  function drawCausticLight() {
    if (mouseX < 0) return;
    const grad = ctx.createRadialGradient(mouseX, mouseY, 0, mouseX, mouseY, 200);
    grad.addColorStop(0, 'rgba(64, 200, 230, 0.04)');
    grad.addColorStop(1, 'transparent');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);
  }

  class Mote {
    constructor() { this.reset(); }
    reset() {
      this.x = Math.random() * W;
      this.y = Math.random() * H;
      this.size = Math.random() * 1.5 + 0.5;
      this.opacity = Math.random() * 0.2 + 0.05;
      this.vx = (Math.random() - 0.5) * 0.3;
      this.vy = (Math.random() - 0.5) * 0.15;
      this.pulse = Math.random() * Math.PI * 2;
      this.pulseSpeed = Math.random() * 0.03 + 0.01;
    }
    update() {
      this.x += this.vx;
      this.y += this.vy;
      this.pulse += this.pulseSpeed;
      if (this.x < 0) this.x = W;
      if (this.x > W) this.x = 0;
      if (this.y < 0) this.y = H;
      if (this.y > H) this.y = 0;
    }
    draw() {
      const alpha = this.opacity * (0.6 + 0.4 * Math.sin(this.pulse));
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(100, 220, 255, ${alpha})`;
      ctx.fill();
    }
  }

  const motes = [];
  for (let i = 0; i < 80; i++) motes.push(new Mote());

  function loop() {
    ctx.clearRect(0, 0, W, H);
    drawCausticLight();
    motes.forEach(m => { m.update(); m.draw(); });
    bubbles.forEach(b => { b.update(); b.draw(); });
    animId = requestAnimationFrame(loop);
  }
  loop();

  function onScroll() {
    const depth = window.scrollY / (document.body.scrollHeight - window.innerHeight);
    const darken = Math.floor(depth * 10);
    document.documentElement.style.setProperty('--bg', `hsl(205, ${80 - darken * 3}%, ${6 - darken * 0.3}%)`);
  }
  window.addEventListener('scroll', onScroll);

  window.__aiCleanup = window.__aiCleanup || [];
  window.__aiCleanup.push(() => {
    cancelAnimationFrame(animId);
    canvas.remove();
    window.removeEventListener('mousemove', onMouseMove);
    window.removeEventListener('resize', resize);
    window.removeEventListener('scroll', onScroll);
  });
})();
